<?php
declare(strict_types=1);define('HWC_SKIP_GLOBAL_SHELL',true);require_once __DIR__.'/config/dynamic_forms.php';
$pdo=role_portal_db();dynamic_forms_ensure($pdo);security_step17_session_start();$user=security_step17_session_user($pdo,true);if(!$user||!in_array((string)$user['role_code'],['admin','coach'],true)){header('Location: access_denied.php');exit;}$ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$key=trim((string)($_GET['form']??$_POST['form_key']??''));$s=$pdo->prepare("SELECT * FROM dynamic_form_definitions WHERE organization_id=? AND form_key=? AND is_custom=1 AND status='active' LIMIT 1");$s->execute([$orgId,$key]);$form=$s->fetch();if(!$form){http_response_code(404);exit('Form not found.');}$s=$pdo->prepare("SELECT * FROM dynamic_form_fields WHERE organization_id=? AND form_id=? AND status='active' ORDER BY sort_order,id");$s->execute([$orgId,(int)$form['id']]);$fields=$s->fetchAll();$options=[];foreach($fields as $f){$q=$pdo->prepare("SELECT * FROM dynamic_form_options WHERE organization_id=? AND field_id=? AND status='active' ORDER BY sort_order,id");$q->execute([$orgId,(int)$f['id']]);$options[(int)$f['id']]=$q->fetchAll();}$csrf=security_step17_csrf();$error=$success=null;
try{if($_SERVER['REQUEST_METHOD']==='POST'){security_step17_verify_csrf((string)($_POST['csrf']??''));$values=[];foreach($fields as $f){$v=$_POST['field'][(string)$f['id']]??'';if(is_array($v))$v=implode(', ',array_map('strval',$v));$v=trim((string)$v);if((int)$f['is_required']===1&&$v==='')throw new RuntimeException($f['field_label'].' is required.');$values[]=[(int)$f['id'],(string)$f['field_key'],(string)$f['field_label'],$v];}$code='CF-'.date('YmdHis').'-'.strtoupper(bin2hex(random_bytes(3)));$pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO dynamic_form_submissions(organization_id,form_id,submission_code,submitted_by,submitted_role) VALUES(?,?,?,?,?)");$q->execute([$orgId,(int)$form['id'],$code,(int)$user['id'],(string)$user['role_code']]);$sid=(int)$pdo->lastInsertId();$q=$pdo->prepare("INSERT INTO dynamic_form_submission_values(organization_id,submission_id,field_id,field_key,field_label,field_value) VALUES(?,?,?,?,?,?)");foreach($values as $v)$q->execute([$orgId,$sid,...$v]);$pdo->commit();security_step17_audit($pdo,(int)$user['id'],'dynamic_form_submitted','dynamic_form_submission',$sid,['form_key'=>$key,'submission_code'=>$code]);$success='Entry saved successfully • '.$code;$_POST=[];}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$h($form['form_name'])?></title><style>*{box-sizing:border-box}body{margin:0;background:#f6f8fd;color:#294036;font-family:Inter,Arial}.wrap{max-width:980px;margin:auto;padding:18px}.hero,.card{padding:18px;border:1px solid #dce6e0;border-radius:18px;background:#fff;margin-bottom:13px}.hero{background:linear-gradient(135deg,#fff,#eef5ff)}h1{margin:0;font-size:1.35rem}p{color:#708078}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.field{display:grid;gap:5px;font-size:.72rem;font-weight:800}.wide{grid-column:1/-1}input,select,textarea{width:100%;padding:11px;border:1px solid #d7e1dc;border-radius:10px;background:#fff}textarea{min-height:95px}.btn{grid-column:1/-1;padding:12px;border:0;border-radius:10px;background:#287b4b;color:#fff;font-weight:850}.msg{padding:11px;border-radius:10px;margin-bottom:12px}.ok{background:#e9f8ef;color:#176d43}.bad{background:#fff0f0;color:#a13a3a}@media(max-width:650px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><main class="wrap"><section class="hero"><h1><?=$h($form['form_name'])?></h1><p><?=$h($form['description'])?></p></section><?php if($success):?><div class="msg ok"><?=$h($success)?></div><?php endif?><?php if($error):?><div class="msg bad"><?=$h($error)?></div><?php endif?><form method="post" class="card grid"><input type="hidden" name="csrf" value="<?=$h($csrf)?>"><input type="hidden" name="form_key" value="<?=$h($key)?>"><?php foreach($fields as $f):$opts=$options[(int)$f['id']]??[];?><label class="field <?=$f['field_type']==='text'&&str_contains(strtolower((string)$f['field_key']),'note')?'wide':''?>"><?=$h($f['field_label'])?><?=$f['is_required']?' *':''?><?php if($f['field_type']==='select'):?><select name="field[<?=(int)$f['id']?>]" <?=$f['is_required']?'required':''?>><option value="">Choose…</option><?php foreach($opts as $o):?><option value="<?=$h($o['option_value'])?>"><?=$h($o['option_label'])?></option><?php endforeach?></select><?php elseif($f['field_type']==='radio'):?><select name="field[<?=(int)$f['id']?>]" <?=$f['is_required']?'required':''?>><option value="">Choose…</option><?php foreach($opts as $o):?><option value="<?=$h($o['option_value'])?>"><?=$h($o['option_label'])?></option><?php endforeach?></select><?php elseif($f['field_type']==='checkbox'):?><select name="field[<?=(int)$f['id']?>]" multiple><?php foreach($opts as $o):?><option value="<?=$h($o['option_value'])?>"><?=$h($o['option_label'])?></option><?php endforeach?></select><?php elseif(str_contains(strtolower((string)$f['field_key']),'note')):?><textarea name="field[<?=(int)$f['id']?>]" <?=$f['is_required']?'required':''?>></textarea><?php else:?><input name="field[<?=(int)$f['id']?>]" <?=$f['is_required']?'required':''?>><?php endif?><?php if($f['help_text']):?><small><?=$h($f['help_text'])?></small><?php endif?></label><?php endforeach?><button class="btn">Save Entry</button></form></main></body></html>
